import { useCallback, useEffect, useMemo, useRef, useState } from 'react';

import { FilterDataAccessor } from 'domain/Filter';
import {
  usePageFilterApplied,
  usePageFilterData,
  usePageFilterManagement,
  usePageFilterStatus,
} from 'hooks';
import { FilterForm } from 'models/Filters';
import {
  buildDrillDownNavigationPath,
  buildGeoRestorePatch,
  deriveEntryGeoAnchor,
  GEO_COUNTRY_STEP,
  GeoAnchor,
  isAllowedNavigationKey,
  isGeoAnchorCaptureReady,
  isGeoStepActive,
  isGeoStepKey,
  resolveBreadcrumbRootLabel,
  shouldIncludeCountryGeoStepInPath,
  shouldPreserveAnchorRootLabel,
  syncGeoNavigationSteps,
} from 'pages/pillars/ValueCreation/utils/drillDownBreadcrumbUtils';

import { DrillDownBreadcrumbConfig, DrillDownBreadcrumbResult } from './types';

const EMPTY_VALUES = new Set(['', 'ALL', 'All']);

export function useDrillDownBreadcrumb<TKey extends string>(
  config: DrillDownBreadcrumbConfig<TKey>,
): DrillDownBreadcrumbResult {
  const {
    pageName,
    goldenPathOrder,
    navOrderParam,
    resetEvent,
    hasSpecificValue,
    buildClearPatch,
  } = config;

  const { applied } = usePageFilterApplied(pageName);
  const { defaults, dataFilters } = usePageFilterData(pageName);
  const { isLoading } = usePageFilterStatus(pageName);
  const { updateAllForm, apply } = usePageFilterManagement(pageName);

  const appliedRef = useRef(applied);
  appliedRef.current = applied;

  const defaultsRef = useRef(defaults);
  defaultsRef.current = defaults;

  const initialUrlZoneRef = useRef(
    new URLSearchParams(globalThis.location.search).get('filter_zone'),
  );
  const initialUrlCountryRef = useRef(
    new URLSearchParams(globalThis.location.search).get('filter_country'),
  );

  const entryGeoAnchorRef = useRef<GeoAnchor | null>(null);
  const [isAnchorReady, setIsAnchorReady] = useState(false);

  useEffect(() => {
    if (isLoading || !applied || entryGeoAnchorRef.current) return;

    if (
      !isGeoAnchorCaptureReady(
        applied,
        initialUrlZoneRef.current,
        initialUrlCountryRef.current,
      )
    ) {
      return;
    }

    const anchor = deriveEntryGeoAnchor(
      applied,
      dataFilters,
      initialUrlCountryRef.current,
    );

    if (!anchor?.rootLabel.trim()) return;

    entryGeoAnchorRef.current = anchor;
    setIsAnchorReady(true);
  }, [applied, dataFilters, isLoading]);

  useEffect(() => {
    if (!isAnchorReady) return;

    const anchor = entryGeoAnchorRef.current;
    if (!anchor || shouldIncludeCountryGeoStepInPath(anchor)) return;

    setNavigationOrder((prev) => {
      if (!prev.includes(GEO_COUNTRY_STEP)) return prev;
      return prev.filter((key) => key !== GEO_COUNTRY_STEP);
    });
  }, [isAnchorReady]);

  useEffect(() => {
    if (!isAnchorReady || !applied) return;

    const anchor = entryGeoAnchorRef.current;
    if (anchor?.mode !== 'crossPageCountry' && anchor?.mode !== 'zone') return;

    if (shouldPreserveAnchorRootLabel(anchor, applied)) return;

    const nextAnchor = deriveEntryGeoAnchor(
      applied,
      dataFilters,
      anchor.mode === 'crossPageCountry' ? null : initialUrlCountryRef.current,
    );

    if (nextAnchor) {
      entryGeoAnchorRef.current = nextAnchor;
    }
  }, [applied, dataFilters, isAnchorReady]);

  const rootLabel = resolveBreadcrumbRootLabel(
    isAnchorReady ? entryGeoAnchorRef.current : null,
    applied,
    dataFilters,
  );

  const [navigationOrder, setNavigationOrder] = useState<string[]>(() => {
    const params = new URLSearchParams(globalThis.location.search);
    const raw = params.get(navOrderParam);
    if (raw) {
      return raw
        .split(',')
        .filter((key) => isAllowedNavigationKey(key, goldenPathOrder));
    }

    return goldenPathOrder.filter((key) => {
      const value = params.get(`filter_${key}`);
      return value !== null && !EMPTY_VALUES.has(value);
    });
  });

  const prevAppliedRef = useRef<FilterForm | undefined>(undefined);

  useEffect(() => {
    const prev = prevAppliedRef.current;
    prevAppliedRef.current = applied;

    if (!prev) {
      const params = new URLSearchParams(globalThis.location.search);
      setNavigationOrder((prevOrder) => {
        const cleaned = prevOrder.filter((key) => {
          if (isGeoStepKey(key)) {
            return isGeoStepActive(key, applied);
          }

          if (hasSpecificValue(applied?.[key as keyof typeof applied])) {
            return true;
          }

          const urlValue = params.get(`filter_${key}`);
          return urlValue !== null && !EMPTY_VALUES.has(urlValue);
        });
        return cleaned.length === prevOrder.length ? prevOrder : cleaned;
      });
      return;
    }

    const anchor = entryGeoAnchorRef.current;

    setNavigationOrder((prevOrder) => {
      let order = [...prevOrder];
      let changed = false;

      if (anchor) {
        const geoOrder = syncGeoNavigationSteps(prev, applied, anchor, order);
        if (geoOrder) {
          order = geoOrder;
          changed = true;
        }
      }

      for (const key of goldenPathOrder) {
        const wasSpecific = hasSpecificValue(prev?.[key]);
        const isSpecific = hasSpecificValue(applied?.[key]);

        if (!wasSpecific && isSpecific && !order.includes(key)) {
          order = [...order, key];
          changed = true;
        } else if (!isSpecific && order.includes(key)) {
          order = order.filter((stepKey) => stepKey !== key);
          changed = true;
        }
      }

      return changed ? order : prevOrder;
    });
  }, [applied, goldenPathOrder, hasSpecificValue]);

  useEffect(() => {
    const handleFilterReset = () => {
      setNavigationOrder([]);
    };

    globalThis.addEventListener(resetEvent, handleFilterReset);
    return () => globalThis.removeEventListener(resetEvent, handleFilterReset);
  }, [resetEvent]);

  const isFirstNavigationMount = useRef(true);

  useEffect(() => {
    if (isFirstNavigationMount.current) {
      isFirstNavigationMount.current = false;
      return;
    }

    const params = new URLSearchParams(globalThis.location.search);
    if (navigationOrder.length > 0) {
      params.set(navOrderParam, navigationOrder.join(','));
    } else {
      params.delete(navOrderParam);
    }

    const queryString = params.toString();
    globalThis.history.replaceState(
      {},
      '',
      queryString ? `?${queryString}` : globalThis.location.pathname,
    );
  }, [navOrderParam, navigationOrder]);

  const accessor = FilterDataAccessor.getInstance();

  const { path, pathWithKeys } = useMemo(
    () =>
      buildDrillDownNavigationPath({
        navigationOrder,
        applied,
        dataFilters,
        anchor: isAnchorReady ? entryGeoAnchorRef.current : null,
        hasSpecificValue,
        accessor,
      }),
    [
      accessor,
      applied,
      dataFilters,
      hasSpecificValue,
      isAnchorReady,
      navigationOrder,
    ],
  );

  const pathWithKeysRef = useRef(pathWithKeys);
  pathWithKeysRef.current = pathWithKeys;

  const navigationOrderRef = useRef(navigationOrder);
  navigationOrderRef.current = navigationOrder;

  const goToStep = useCallback(
    (pathIndex: number) => {
      const anchor = entryGeoAnchorRef.current;
      const chips = pathWithKeysRef.current;
      const currentNavigationOrder = navigationOrderRef.current;

      const keysToKeep = new Set(
        pathIndex >= 0
          ? chips.slice(0, pathIndex + 1).map((chip) => chip.key)
          : [],
      );

      const filterKeysToKeep = new Set(
        [...keysToKeep].filter(
          (key): key is TKey => !isGeoStepKey(key),
        ) as TKey[],
      );
      const filterKeysToClean = goldenPathOrder.filter(
        (key) => !filterKeysToKeep.has(key),
      );

      const geoKeysToClean = currentNavigationOrder.filter(
        (key) => isGeoStepKey(key) && !keysToKeep.has(key),
      );
      const shouldRestoreGeo = pathIndex < 0 || geoKeysToClean.length > 0;
      const geoPatch =
        anchor && shouldRestoreGeo
          ? buildGeoRestorePatch(keysToKeep, anchor)
          : {};
      const currentApplied = appliedRef.current;
      const clearedFilters = buildClearPatch(
        defaultsRef.current,
        filterKeysToClean,
        filterKeysToKeep,
        currentApplied,
      );

      const hasGeoRestore = Object.keys(geoPatch).length > 0;
      const hasFilterClear = filterKeysToClean.length > 0;

      if (!hasGeoRestore && !hasFilterClear) return;

      const nextNavigationOrder =
        pathIndex < 0
          ? []
          : currentNavigationOrder.filter((key) => keysToKeep.has(key));

      setNavigationOrder(nextNavigationOrder);

      if (!currentApplied) return;

      updateAllForm({
        ...currentApplied,
        ...clearedFilters,
        ...geoPatch,
      });
      apply();
    },
    [apply, buildClearPatch, goldenPathOrder, updateAllForm],
  );

  return { rootLabel, path, goToStep, isLoading };
}
